// The types of the reference data of the accuracy tests (the tables: data/<group>.hpp, generated by
// generateReferenceData.cpp). Values are double: exact for the inputs and results of float32_t and float64_t.
#pragma once

namespace csLie::testReference {

/// a rotation matrix (row major, exactly representable in the tested precision) and its exact log
struct So3LogCase {
  char const *label;
  double R[9];
  double omega[3];
};

/// a rotation vector (exactly representable in the tested precision) and its exact exp (row major)
struct So3ExpCase {
  char const *label;
  double omega[3];
  double R[9];
};

/// an angle (exactly representable in the tested precision) and its exact exp coefficients
/// A = sin(theta) / theta, B = (1 - cos(theta)) / theta^2
struct CoeffCase {
  char const *label;
  double theta;
  double A;
  double B;
};

} // namespace csLie::testReference
